endmodule sram_controller (
    input clk,
    input reset,
    input addr_inc,
    input [14:0] sram_addr,
    input [31:0] in_data,
    output reg [31:0] out_data,
    output reg [14:0] sram_addr_out,
    input [31:0] sram_do,
    output sram_ce_n,
    output sram_oe_n,
    output sram_we_n,
    output [15:0] sram_addr_out_hi,
    output reg [15:0] sram_addr_inc,
    input [31:0] sram_d,
    input sram_rdy
);
    reg [1:0] state;
    reg [14:0] next_addr;
    reg [31:0] data_buf;
    reg ce_n;
    reg oe_n;
    reg we_n;
    reg [31:0] d;
    always @(posedge clk) begin
        if (reset) begin
            state <= 2'b00;
            next_addr <= 15'h0000;
            ce_n <= 1'b1;
            oe_n <= 1'b1;
            we_n <= 1'b1;
            d <= 32'd0;
            sram_addr_inc <= 16'h0000;
        end else begin
            case (state)
                2'b00: begin // IDLE
                    state <= 2'b01;
                    next_addr <= sram_addr;
                    d <= in_data;
                    ce_n <= 1'b0;
                    we_n <= 1'b0;
                    oe_n <= 1'b1;
                end
                2'b01: begin // ADDR_LOW
                    state <= 2'b10;
                    ce_n <= 1'b0;
                    we_n <= 1'b0;
                    oe_n <= 1'b1;
                end
                2'b10: begin // ADDR_HIGH
                    state <= 2'b11;
                    ce_n <= 1'b0;
                    we_n <= 1'b0;
                    oe_n <= 1'b1;
                end
                2'b11: begin // READ
                    state <= 2'b00;
                    if (addr_inc) next_addr <= next_addr + 1'b1;
                    out_data <= sram_do;
                    ce_n <= 1'b1;
                    we_n <= 1'b1;
                    oe_n <= 1'b0;
                end
            endcase
            if (state == 2'b00 && !sram_rdy) begin
                state <= 2'b01;
                next_addr <= sram_addr;
                d <= in_data;
                ce_n <= 1'b0;
                we_n <= 1'b0;
                oe_n <= 1'b1;
            end
            if (state == 2'b11 && sram_rdy) begin
                state <= 2'b00;
                out_data <= sram_d;
                if (addr_inc) next_addr <= next_addr + 1'b1;
                ce_n <= 1'b1;
                we_n <= 1'b1;
                oe_n <= 1'b1;
            end
            sram_addr_out <= next_addr;
            sram_addr_out_hi <= next_addr[15:0];
            if (addr_inc) sram_addr_inc <= next_addr[15:0] + 1'b1;
        end
    end
    assign sram_ce_n = ce_n;
    assign sram_oe_n = oe_n;
    assign sram_we_n = we_n;
    assign sram_di = d[7:0];
    assign sram_dh = d[15:8];
    assign sram_dl = d[23:16];
    assign sram_dhh = d[31:24];
endmodule
